import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import api from '../../services/api';

export default function EnrollForm() {
  const { user }            = useAuth();
  const navigate            = useNavigate();
  const [sections, setSections] = useState([]);
  const [selected, setSelected] = useState('');
  const [loading,  setLoading]  = useState(true);
  const [saving,   setSaving]   = useState(false);
  const [error,    setError]    = useState('');
  const [success,  setSuccess]  = useState('');

  // Carga secciones disponibles
  useEffect(() => {
    api.get('/api/sections')
      .then((r) => setSections(r.data))
      .catch(() => setError('No se pudieron cargar las secciones.'))
      .finally(() => setLoading(false));
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!selected) { setError('Selecciona una sección.'); return; }
    setSaving(true);
    setError('');
    try {
      await api.post('/api/enrollments/enroll', {
        studentId: user.id,
        sectionId: Number(selected),
      });
      setSuccess('¡Inscripción exitosa!');
      setTimeout(() => navigate('/my-enrollments'), 1500);
    } catch (err) {
      const msg = err.response?.data?.message ?? err.response?.data ?? '';
      if (msg.toString().includes('prerequisit') || msg.toString().includes('requisito')) {
        setError('No cumples los prerrequisitos para esta asignatura.');
      } else if (msg.toString().includes('cupo') || msg.toString().includes('slot')) {
        setError('No hay cupos disponibles en esta sección.');
      } else if (err.response?.status === 409) {
        setError('Ya estás inscrito en esta asignatura.');
      } else {
        setError('No se pudo completar la inscripción. Verifica los prerrequisitos.');
      }
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="container py-4" style={{ maxWidth: 540 }}>
      <div className="d-flex align-items-center gap-3 mb-4">
        <button className="btn btn-sm btn-outline-secondary" onClick={() => navigate('/my-enrollments')}>
          ← Volver
        </button>
        <h2 className="fw-bold mb-0">Inscribir Asignatura</h2>
      </div>

      <div className="card border-0 shadow-sm">
        <div className="card-body p-4">

          {error   && <div className="alert alert-danger py-2">{error}</div>}
          {success && <div className="alert alert-success py-2">{success}</div>}

          {loading ? <p className="text-muted">Cargando secciones...</p> : (
            <form onSubmit={handleSubmit}>
              <div className="mb-4">
                <label className="form-label fw-medium">Sección disponible</label>
                <select
                  className="form-select"
                  value={selected}
                  onChange={(e) => { setSelected(e.target.value); setError(''); }}
                >
                  <option value="">— Selecciona una sección —</option>
                  {sections.map((s) => (
                    <option key={s.id} value={s.id}>
                      {s.subjectName ?? s.subjectCode} — Sección {s.sectionCode ?? s.id}
                      {s.availableSlots != null ? ` (${s.availableSlots} cupos)` : ''}
                    </option>
                  ))}
                </select>
                <div className="form-text text-muted">
                  Solo se muestran secciones del semestre activo.
                </div>
              </div>

              <button
                type="submit"
                className="btn w-100 text-white fw-semibold"
                style={{ backgroundColor: '#003366' }}
                disabled={saving}
              >
                {saving ? (
                  <><span className="spinner-border spinner-border-sm me-2" />Inscribiendo...</>
                ) : 'Confirmar inscripción'}
              </button>
            </form>
          )}
        </div>
      </div>
    </div>
  );
}
